roup(1).strip() if v_match else None\\n        \\n        # Handle amount with potential spaces or symbols\\n        a_match = re.search(r\\\"Total\\\\s*\\\\$?\\\\s*([\\\\d\\\\.]+)\\\", text)\\n        amount_pdf = float(a_match.group(1)) if a_match else 0.0\\n        \\n        i_match = re.search(r\\\"Payment IBAN:\\\\s*(.+)\\\", text)\\n        iban_pdf = i_match.group(1).strip() if i_match else None\\n        \\n        p_match = re.search(r\\\"PO Number:\\\\s*(.+)\\\", text)\\n        po_pdf = p_match.group(1).strip() if p_match else None\\n        \\n        reason = None\\n        matched_vendor_row = None\\n        \\n        # Check 1: Unknown Vendor\\n        # Using RapidFuzz for fuzzy matching. Threshold 80 handles minor typos.\\n        # We accept the best match if score \u003e= 80.\\n        match = process.extractOne(vendor_name_pdf, vendor_names, scorer=fuzz.ratio)\\n        if match and match[1] \u003e= 80:\\n            matched_vendor_name = match[0]\\n            matched_vendor_row = vendors[vendors['name'] == matched_vendor_name].iloc[0]\\n        else:\\n            reason = \\\"Unknown Vendor\\\"\\n            \\n        # Check 2: IBAN Mismatch\\n        if not reason:\\n            expected_iban = matched_vendor_row['iban']\\n            # Simple string comparison\\n            if expected_iban != iban_pdf:\\n                reason = \\\"IBAN Mismatch\\\"\\n                \\n        po_row = None\\n        # Check 3: Invalid PO\\n        if not reason:\\n            if po_pdf is None:\\n                reason = \\\"Invalid PO\\\"\\n            else:\\n                # Check if PO exists in CSV\\n                po_matches = pos[pos['po_number'] == po_pdf]\\n                if po_matches.empty:\\n                    reason = \\\"Invalid PO\\\"\\n                else:\\n                    po_row = po_matches.iloc[0]\\n                    \\n        # Check 4: Amount Mismatch\\n        if not reason:\\n            # Tolerance of 0.01\\n            if abs(po_row['amount'] - amount_pdf) \u003e 0.01:\\n                reason = \\\"Amount Mismatch\\\"\\n                \\n        # Check 5: Vendor Mismatch\\n        if not reason:\\n            # Check if the PO's vendor ID matches the identified vendor's ID\\n            if po_row['vendor_id'] != matched_vendor_row['id']:\\n                reason = \\\"Vendor Mismatch\\\"\\n                \\n        if reason:\\n            fraud_report.append({\\n                \\\"invoice_page_number\\\": page_num,\\n                \\\"vendor_name\\\": vendor_name_pdf,\\n                \\\"invoice_amount\\\": amount_pdf,\\n                \\\"iban\\\": iban_pdf,\\n                \\\"po_number\\\": po_pdf,\\n                \\\"reason\\\": reason\\n            })\\n\\nwith open('/root/fraud_report.json', 'w') as f:\\n    json.dump(fraud_report, f, indent=2)\\n    \\nprint(f\\\"Processed {len(pdf.pages)} pages. Found {len(fraud_report)} fraudulent invoices.\\\")\\nEOF\\npython3 solve_fraud.py\\n\",\n\"duration\": 15.0\n},\n{\n\"keystrokes\": \"head -n 20 /root/fraud_report.json\\n\",\n\"duration\": 0.1\n}\n]\n}",
